import sys

def main():
    data = sys.stdin.read().split()
    idx = 0
    n = int(data[idx]); idx += 1

    word_to_topic = {}
    for _ in range(n):
        name = data[idx]; idx += 1
        k = int(data[idx]); idx += 1
        for _ in range(k):
            w = data[idx]; idx += 1
            word_to_topic[w] = name

    x = int(data[idx]); idx += 1
    counts = {}
    for _ in range(x):
        w = data[idx]; idx += 1
        t = word_to_topic.get(w)
        if t is not None:
            counts[t] = counts.get(t, 0) + 1

    best = min(counts, key=lambda t: (-counts[t], t))
    print(best)

main()
